  "outcome": "answer",
  "confidence": "high",
  "answer": "The behavior you're experiencing is due to how Streamlit handles forms and session state. When using a form, the script only reruns and updates the session state after the form is submitted, which can lead to the observed behavior of needing to submit twice for the state to update correctly. To ensure the session state updates as expected, you should use the unique key assigned to the widget rather than the variable it is assigned to when updating the session state. This is a common issue when managing state in forms.",
  "claims": [
    {
      "claim_id": "1",
      "text": "For widgets inside a form, any changes made by a user do not get passed to the Python backend until the form is submitted.",
      "citation_ids": ["S1"]
    },
    {
      "claim_id": "2",
      "text": "When using session state to update widgets or values in your script, you need to use the unique key you assigned to the widget, not the variable that you assigned your widget to.",
      "citation_ids": ["S4"]
    }
  ],
  "citations": ["S1", "S4"]
}

